// Arithmetic series sum: 1 + 2 + ... + n
// Assumption from the problem statement: the exact result is < 10_000,
// so it fits comfortably in u64 and no overflow occurs.

pub fn compute_arith_sum(n: u64) -> u64 {
    let mut idx: u64 = 0;
    let mut sum: u64 = 0;

    // Loop invariant (informal):
    // - 0 <= idx <= n
    // - sum == 1 + 2 + ... + idx
    while idx < n {
        idx += 1;
        sum += idx;
    }

    sum
}